INSERT INTO `kpi_rules` (`id`, `code`, `name`, `deduction_points`, `description`, `category`) VALUES
(1, 'L01', 'Đi học muộn (sau 7h00 truy bài / sau 7h15 vào tiết 1)', 1, 'Nội quy nhà trường; Khóa 5 cửa phụ Inox', 'nề_nếp_học_đường'),
(2, 'L02', 'Mặc sai đồng phục, không đeo thẻ học sinh, không đi giày/dép có quai', 3, 'Nội quy trang phục học đường', 'nề_nếp_học_đường'),
(3, 'L03', 'Gửi xe sai vị trí nhà xe quy định (HS KTX không gửi xe ở sân KTX)', 3, 'Nội quy nhà xe & phân luồng khối', 'ký_túc_xá'),
(4, 'L04', 'Ăn vặt trong lớp học, vừa đi vừa ăn trong sân trường / Đến canteen giờ học', 3, 'Nội quy vệ sinh & văn hóa ứng xử', 'nề_nếp_học_đường'),
(5, 'L05', 'Sử dụng điện thoại/thiết bị điện tử trong giờ học khi chưa có phép GV', 5, 'Thông tư 15/2026/TT-BGDĐT; Nội quy', 'kỷ_luật_lớp_học'),
(6, 'L06', 'Không tắt đèn, quạt, bảng tương tác, điều hòa khi kết thúc buổi học', 5, 'Nội quy tiết kiệm năng lượng & tài sản', 'tiết_kiệm_năng_lượng'),
(7, 'L07', 'Vi phạm KTX: Treo ri-đô, đồ đạc bừa bãi ngoài hành lang, mất vệ sinh WC/phòng', 3, 'Nội quy KTX tòa nhà A (Chốt 7h15)', 'ký_túc_xá'),
(8, 'L08', 'Mất trật tự trong giờ học, ứng xử thiếu văn hóa, nói tục chửi thề', 3, 'Quy tắc ứng xử học đường', 'kỷ_luật_lớp_học'),
(9, 'L09', 'Gian lận trong kiểm tra/thi cử, lạm dụng AI làm bài thay (Vi phạm nghiêm trọng)', 10, 'Chương trình liêm chính GD 2026; TT 22', 'liêm_chính_kỷ_luật'),
(10, 'L10', 'Hút thuốc lá, thuốc lá điện tử, mang chất cấm (Trực tiếp xếp Chưa đạt)', 20, 'Quy định cấm thuốc lá học đường', 'liêm_chính_kỷ_luật'),
(11, 'C01', 'Đạt giải HSG các cấp, NCKH, đóng góp tích cực cho CLB / Trường học hạnh phúc', 5, 'Quy chế thi đua khen thưởng', 'khen_thưởng'),
(12, 'C02', 'Gương người tốt việc tốt, nhặt được của rơi trả lại, hỗ trợ bạn học', 3, 'Phong trào thi đua Đoàn trường', 'khen_thưởng'),
(13, 'C03', 'Trực tuần xuất sắc, vệ sinh lớp sạch đẹp toàn diện trong tuần', 2, 'Đánh giá Đội Cờ đỏ / Thanh tra', 'khen_thưởng');
